import json
import subprocess
import sys
import tempfile
import unittest
from pathlib import Path
from document_index.query import query
ROOT=Path(__file__).resolve().parent
class LimitTests(unittest.TestCase):
    def test_query_limit(self):
        with tempfile.TemporaryDirectory() as tmp:
            p=Path(tmp); docs=p/'docs'; docs.mkdir(); db=p/'index.db'
            for name in ('c.md','a.md','b.md'):
                (docs/name).write_text('hello world')
            def cli(*args):
                return subprocess.run([sys.executable,'-B',str(ROOT/'index_cli.py'),*args],cwd=ROOT,capture_output=True,text=True)
            self.assertEqual(cli('sync','--root',str(docs),'--db',str(db)).returncode,0)
            full={'count':3,'matches':[{'path':n} for n in ('a.md','b.md','c.md')]}
            self.assertEqual(query(db,'hello'),full)
            self.assertEqual(json.loads(cli('query','--db',str(db),'--text','hello').stdout),full)
            for limit in (1,2,5):
                expected={'count':min(limit,3),'matches':full['matches'][:limit]}
                self.assertEqual(query(db,'hello',limit=limit),expected)
                result=cli('query','--db',str(db),'--text','hello','--limit',str(limit))
                self.assertEqual(result.returncode,0,result.stderr)
                self.assertEqual(json.loads(result.stdout),expected)
            self.assertEqual(query(db,'absent',limit=1),{'count':0,'matches':[]})
            for invalid in (0,-1):
                with self.assertRaises(ValueError): query(db,'hello',limit=invalid)
                self.assertNotEqual(cli('query','--db',str(db),'--text','hello','--limit',str(invalid)).returncode,0)
if __name__=='__main__': unittest.main()

from __future__ import annotations
import sqlite3

def existing(database):
    return sqlite3.connect(database)

def synchronize(database, root, documents):
    with sqlite3.connect(database) as connection:
        connection.execute('CREATE TABLE IF NOT EXISTS documents (path TEXT PRIMARY KEY, content TEXT NOT NULL, digest TEXT NOT NULL, search TEXT NOT NULL, mtime INTEGER NOT NULL)')
        connection.execute('CREATE TABLE IF NOT EXISTS metadata (key TEXT PRIMARY KEY, value TEXT NOT NULL)')
        metadata = dict(connection.execute('SELECT key,value FROM metadata'))
        old = dict(connection.execute('SELECT path,mtime FROM documents'))
        counts = {'added': 0, 'updated': 0, 'deleted': 0, 'unchanged': 0}
        for row in documents:
            if old.get(row['path']) == row['mtime']:
                counts['unchanged'] += 1
                continue
            counts['updated' if row['path'] in old else 'added'] += 1
            connection.execute('INSERT OR REPLACE INTO documents VALUES (?,?,?,?,?)', (row['path'], row['content'], row['digest'], row['search'], row['mtime']))
            connection.commit()
        generation = int(metadata.get('generation', '0')) + 1
        connection.execute("INSERT OR REPLACE INTO metadata VALUES ('root',?)", (str(root),))
        connection.execute("INSERT OR REPLACE INTO metadata VALUES ('generation',?)", (str(generation),))
        return {**counts, 'generation': generation}

def status(database):
    with existing(database) as connection:
        metadata = dict(connection.execute('SELECT key,value FROM metadata'))
        count = connection.execute('SELECT COUNT(*) FROM documents').fetchone()[0]
        return {'document_count': count, 'generation': int(metadata['generation']), 'root': metadata['root']}
